// ---------------------------------------------------------
// urob's Timeless Home Row / Bottom Row Mods (QMK Native Engine)
// ---------------------------------------------------------
// 1. Tapping Term (280ms): Generous duration for comfortable modifier holds without misfires.
#undef TAPPING_TERM
#define TAPPING_TERM 280

// 2. Permissive Hold: Decisively settles a mod-tap key as held when another key is tapped during the hold.
#undef PERMISSIVE_HOLD
#define PERMISSIVE_HOLD

// 3. Hold on Other Key Press (Per Key): Instant 0ms hold on opposite hand press ONLY for Shift keys.
#undef HOLD_ON_OTHER_KEY_PRESS
#ifndef HOLD_ON_OTHER_KEY_PRESS_PER_KEY
#define HOLD_ON_OTHER_KEY_PRESS_PER_KEY
#endif

// 4. Flow Tap Term (150ms): If typed rapidly within 150ms of a preceding alpha key, settles mod-tap as a tap.
#undef FLOW_TAP_TERM
#define FLOW_TAP_TERM 150

// 5. Chordal Hold: Uses the handedness matrix to enforce the Opposite Hands Rule.
//    - Cross-hand chords (e.g. Left Shift + Right Alpha) -> Instant Hold.
//    - Same-hand rolls (e.g. Left Shift + Left Alpha) -> Immediate Tap (prevents rolling misfires).
#ifndef CHORDAL_HOLD
#define CHORDAL_HOLD
#endif

// 6. Quick Tap Term (0ms): Disables the double-tap auto-repeat behavior to prevent unwanted repeats.
#undef QUICK_TAP_TERM
#define QUICK_TAP_TERM 0

// Fast, responsive combos
#undef COMBO_TERM
#define COMBO_TERM 40

// Disable the Leader timer entirely for stress-free single-key macros
#define LEADER_NO_TIMEOUT

// Mouse Key Tuning (Near-constant speed, minimal acceleration)
#define MK_COMBINED
#define MK_COMBINED_ACL1_SPEED 20
#define MOUSEKEY_MOVE_DELTA   14
#define MOUSEKEY_DELAY        0
